using UnifiedRgb.Core.Color;
using UnifiedRgb.Devices;
using static UnifiedRgb.Core.Effects.EffectMath;

namespace UnifiedRgb.Core.Effects.Generators;

/// <summary>渐变缎带 Gradient Ribbon: A smooth gradient through the palette (rainbow if empty) scrolls along u.</summary>
public sealed class GradientRibbonEffect : EffectGenerator, ILoopable
{
    public const string EffectId = "GradientRibbon";

    public GradientRibbonEffect()
        : base(EffectId, new EffectParamSchema("Gradient Ribbon", "渐变缎带", 0, 7, true, true, EffectMath.Trio, false))
    {
    }

    public override void Render(in RenderContext ctx, Span<Rgb> output)
    {
        var ph = ctx.Phase(0.02, 0.4);
        var cnt = Math.Max(ctx.Colors.Length, 2);
        for (var i = 0; i < output.Length; i++)
        {
            var x = Frac((0.5 * ctx.U(i)) - ph);
            if (ctx.Colors.Length == 0)
            {
                output[i] = ColorTables.RainbowAt(x);
                continue;
            }

            var p = x * cnt;
            var k = (long)p;
            output[i] = Lerp(ctx.Color(k), ctx.Color(k + 1), p - k);
        }
    }

    public double LoopSeconds(in EffectParams p) => LoopPeriod.Cycles(p, 0.02, 0.4, 1);
}
